:root {
  --ink: #16181d;
  --ink-soft: #4a4f5c;
  --muted: #6b7180;
  --line: #e4e6eb;
  --bg: #ffffff;
  --bg-alt: #f6f7f9;
  --accent: #3b5bdb;
  --accent-dark: #2f4ac0;
  --accent-tint: #edf1ff;
  --radius: 12px;
  --shadow: 0 1px 2px rgba(22, 24, 29, 0.06), 0 8px 24px rgba(22, 24, 29, 0.08);
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  * {
    transition: none !important;
  }
}

body {
  margin: 0;
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 {
  line-height: 1.2;
  margin: 0 0 0.5em;
  letter-spacing: -0.01em;
}

h1 { font-size: clamp(2rem, 4.5vw, 3.1rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.6rem, 3vw, 2.2rem); }
h3 { font-size: 1.15rem; }

p { margin: 0 0 1em; }

a { color: var(--accent); }

a:focus-visible,
button:focus-visible,
input:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 0 24px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 8px;
  background: var(--ink);
  color: #fff;
  padding: 8px 12px;
  border-radius: 6px;
  z-index: 100;
}
.skip-link:focus { left: 8px; }

/* Buttons */
.btn {
  display: inline-block;
  padding: 12px 20px;
  border-radius: 8px;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border: 1px solid var(--accent);
  transition: background 0.15s ease, border-color 0.15s ease;
}
.btn:hover { background: var(--accent-dark); border-color: var(--accent-dark); }

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line);
}
.btn-ghost:hover { background: var(--bg-alt); border-color: #cfd3db; }

.btn-small { padding: 8px 14px; font-size: 0.9rem; }
.btn-block { display: block; text-align: center; width: 100%; }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: saturate(180%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  height: 64px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--ink);
  text-decoration: none;
}
.brand-mark {
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: var(--accent);
  box-shadow: inset 0 -6px 0 rgba(255, 255, 255, 0.35);
}
.nav-links {
  display: flex;
  gap: 28px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.nav-links a {
  color: var(--ink-soft);
  text-decoration: none;
  font-weight: 500;
}
.nav-links a:hover { color: var(--ink); }

/* Hero */
.hero {
  padding: 80px 0 88px;
  background: linear-gradient(180deg, var(--accent-tint) 0%, var(--bg) 100%);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 56px;
  align-items: center;
}
.lede {
  font-size: 1.15rem;
  color: var(--ink-soft);
  max-width: 34em;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 28px 0 14px;
}
.fine {
  font-size: 0.875rem;
  color: var(--muted);
}

.hero-card {
  margin: 0;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
}
.card-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-bottom: 12px;
  margin-bottom: 8px;
  border-bottom: 1px solid var(--line);
}
.card-title { font-weight: 700; }
.card-meta { font-size: 0.85rem; color: var(--muted); }

.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.task-list li {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}
.task-list li:last-child { border-bottom: 0; }
.task-list input {
  width: 18px;
  height: 18px;
  margin-top: 3px;
  accent-color: var(--accent);
  flex-shrink: 0;
}
.task-list label { cursor: pointer; }
.task-list label strong { display: block; font-weight: 600; }
.task-list label span { font-size: 0.85rem; color: var(--muted); }
.task-list input:checked + label strong {
  text-decoration: line-through;
  color: var(--muted);
}
.hero-card figcaption {
  margin-top: 8px;
  font-size: 0.8rem;
  color: var(--muted);
}

/* Sections */
.section { padding: 88px 0; }
.section-alt { background: var(--bg-alt); }
.section h2 { text-align: center; }
.section-intro {
  text-align: center;
  color: var(--ink-soft);
  max-width: 36em;
  margin: 0 auto 48px;
}

/* Features */
.features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.feature {
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
}
.feature p { color: var(--ink-soft); margin: 0; }
.feature-icon {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: var(--accent-tint);
  color: var(--accent);
  font-weight: 700;
  margin-bottom: 16px;
}

/* Testimonials */
.testimonials {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.testimonial {
  margin: 0;
  padding: 32px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.testimonial blockquote {
  margin: 0 0 24px;
  font-size: 1.1rem;
  line-height: 1.55;
}
.testimonial blockquote p { margin: 0; }
.testimonial figcaption {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 0.9rem;
  color: var(--ink-soft);
}
.testimonial figcaption strong { color: var(--ink); }
.avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--accent-tint);
  color: var(--accent);
  font-weight: 700;
  font-size: 0.9rem;
  flex-shrink: 0;
}

/* Pricing */
.billing-toggle {
  display: flex;
  justify-content: center;
  gap: 4px;
  width: max-content;
  margin: -16px auto 40px;
  padding: 4px;
  background: var(--bg-alt);
  border: 1px solid var(--line);
  border-radius: 999px;
}
.toggle-btn {
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  padding: 8px 18px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--ink-soft);
  cursor: pointer;
}
.toggle-btn.is-active {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(22, 24, 29, 0.12);
}
.save {
  font-size: 0.75rem;
  color: var(--accent);
  margin-left: 4px;
}

.plans {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 380px));
  justify-content: center;
  gap: 24px;
}
.plan {
  position: relative;
  padding: 32px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fff;
  display: flex;
  flex-direction: column;
}
.plan-featured {
  border: 2px solid var(--accent);
  box-shadow: var(--shadow);
}
.badge {
  position: absolute;
  top: -13px;
  left: 32px;
  margin: 0;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 700;
}
.plan-desc { color: var(--ink-soft); min-height: 3.2em; }
.price { margin: 8px 0 0; display: flex; align-items: baseline; gap: 6px; }
.amount { font-size: 2.6rem; font-weight: 800; letter-spacing: -0.02em; }
.per { color: var(--muted); }
.billed { font-size: 0.85rem; color: var(--muted); margin-bottom: 24px; }
.plan-features {
  list-style: none;
  padding: 0;
  margin: 0 0 32px;
  flex-grow: 1;
}
.plan-features li {
  position: relative;
  padding: 6px 0 6px 28px;
}
.plan-features li::before {
  content: "";
  position: absolute;
  left: 2px;
  top: 12px;
  width: 12px;
  height: 7px;
  border-left: 2px solid var(--accent);
  border-bottom: 2px solid var(--accent);
  transform: rotate(-45deg);
}

/* Footer */
.site-footer {
  border-top: 1px solid var(--line);
  padding: 28px 0;
  font-size: 0.9rem;
  color: var(--muted);
}
.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}
.footer-inner p { margin: 0; }
.footer-links {
  display: flex;
  gap: 20px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.footer-links a { color: var(--muted); text-decoration: none; }
.footer-links a:hover { color: var(--ink); }

/* Responsive */
@media (max-width: 900px) {
  .hero-grid { grid-template-columns: 1fr; gap: 40px; }
  .features { grid-template-columns: 1fr; }
  .testimonials { grid-template-columns: 1fr; }
}

@media (max-width: 700px) {
  .nav-links { display: none; }
  .hero { padding: 56px 0 64px; }
  .section { padding: 64px 0; }
  .plans { grid-template-columns: 1fr; }
  .plan-desc { min-height: 0; }
  .footer-inner { flex-direction: column; }
}

